/* Initial B_n seeds generated by folding; mutations use the shared exact engine. */
(function(root,factory){
  const api=factory(typeof module==='object'&&module.exports?require('./data/type-b-initial.js'):root.NOBY_B_INITIAL);
  if(typeof module==='object'&&module.exports)module.exports=api;
  root.NObyTypeB=api;
})(globalThis,function(data){
  'use strict';
  function initialSeed(n){
    if(!Number.isInteger(n)||!data?.[n])throw new Error('Choose B rank 2–6.');
    return JSON.parse(JSON.stringify(data[n]));
  }
  function b2Record(sequence,catalogue){
    let id=0;
    for(const k of sequence){
      const edge=catalogue.directedEdges.find(([from,direction])=>from===id&&direction===k);
      if(!edge)throw new Error('Invalid B2 mutation direction.');
      id=edge[2];
    }
    return catalogue.seeds.find(s=>s.id===id);
  }
  return {initialSeed,b2Record};
});
